Cmis800GZr3x200GTransceiver::Cmis800GZr3x200GTransceiver(
    int module,
    TransceiverManager* mgr)
    : Cmis800GZrTransceiver(module, mgr) {
  // Advertise the 3x200G FlexO-6e-DPO application as AppSel 9 (Page 01h bytes
  // 223-226): host 200GAUI-2 (0x4E), media 0x6A, 2 host lanes and 1 media lane,
  // host datapaths starting at lanes 0, 2 and 4
  TransceiverAccessParameter pageParam(
      TransceiverAccessParameter::ADDR_QSFP, 127, 1);
  uint8_t page01 = 0x01;
  writeTransceiver(pageParam, &page01, 0, 0);
  TransceiverAccessParameter appParam(
      TransceiverAccessParameter::ADDR_QSFP, 223, 4);
  std::array<uint8_t, 4> app9 = {0x4E, 0x6A, 0x21, 0x15};
  writeTransceiver(appParam, app9.data(), 0, 0);
  setAppSelGatedDatapath();
}

Cmis800GZrNoHoldOffTmrTransceiver::Cmis800GZrNoHoldOffTmrTransceiver(
    int module,
    TransceiverManager* mgr)
    : Cmis800GZrTransceiver(module, mgr) {
  // Clear rxConsActHoldOffTmrImpl (Page 45h, Byte 129, Bit 2) so the module
  // reports it does NOT support programming the Rx Consequent Action hold-off
  // timer. The CONS_ACT_HOLD_OFF_TMR register (Page 38h) stays 0.
  TransceiverAccessParameter pageParam(
      TransceiverAccessParameter::ADDR_QSFP, 127, 1);
  uint8_t page45 = 0x45;
  writeTransceiver(pageParam, &page45, 0, 0);
  TransceiverAccessParameter provParam(
      TransceiverAccessParameter::ADDR_QSFP, 129, 1);
  uint8_t provVal = 0x7f & ~0x04; // clear rxConsActHoldOffTmrImpl (bit 2)
  writeTransceiver(provParam, &provVal, 0, 0);
}

Cmis2x800GDr4CustomFeatureTransceiver::Cmis2x800GDr4CustomFeatureTransceiver(
    int module,
    TransceiverManager* mgr)
    : Cmis2x800GDr4Transceiver(module, mgr) {
  // Advertise all three Meta custom features in Page 01h Byte 191. Byte 255 is
  // the Page 01h checksum covering Byte 191, so bump it by the same delta
  // (base 0x60 + 0x07) to keep the page consistent.
  TransceiverAccessParameter pageParam(
      TransceiverAccessParameter::ADDR_QSFP, 127, 1);
  uint8_t page01 = 0x01;
  writeTransceiver(pageParam, &page01, 0, 0);
  TransceiverAccessParameter customParam(
      TransceiverAccessParameter::ADDR_QSFP, 191, 1);
  uint8_t customFeatures = 0x07;
  writeTransceiver(customParam, &customFeatures, 0, 0);
  TransceiverAccessParameter csumParam(
      TransceiverAccessParameter::ADDR_QSFP, 255, 1);
  uint8_t checksum = 0x67;
  writeTransceiver(csumParam, &checksum, 0, 0);
}

Cmis2x800GDr4Cmis50Transceiver::Cmis2x800GDr4Cmis50Transceiver(
    int module,
    TransceiverManager* mgr)
    : Cmis2x800GDr4CustomFeatureTransceiver(module, mgr) {
  // Lower Page Byte 1 (RevisionCompliance): major 5, minor 0. Below CMIS 5.1
  // the custom-feature byte must be ignored.
  TransceiverAccessParameter revParam(
      TransceiverAccessParameter::ADDR_QSFP, 1, 1);
  uint8_t revision = 0x50;
  writeTransceiver(revParam, &revision, 0, 0);
}

Cmis2x800GDr4NegativeMarginTransceiver::Cmis2x800GDr4NegativeMarginTransceiver(
    int module,
    TransceiverManager* mgr)
    : Cmis2x800GDr4CustomFeatureTransceiver(module, mgr) {
  // Byte 67: assert ModeMismatchFlag, DSPTempNegativeMarginFlag and
  // LaserTempNegativeMarginFlag. Bytes 68-69: -8 and -4 quarter-degrees,
  // i.e. -2.0 C and -1.0 C.
  TransceiverAccessParameter customParam(
      TransceiverAccessParameter::ADDR_QSFP, 67, 3);
  std::array<uint8_t, 3> customBytes = {0x07, 0xf8, 0xfc};
  writeTransceiver(customParam, customBytes.data(), 0, 0);

  // Page 14h Byte 130: host lanes 0 and 2 mismatched. Byte 131: the single
  // media lane mismatched.
  TransceiverAccessParameter pageParam(
      TransceiverAccessParameter::ADDR_QSFP, 127, 1);
  uint8_t page14 = 0x14;
  writeTransceiver(pageParam, &page14, 0, 0);
  TransceiverAccessParameter mismatchParam(
      TransceiverAccessParameter::ADDR_QSFP, 130, 2);
  std::array<uint8_t, 2> mismatchBytes = {0x05, 0x01};
  writeTransceiver(mismatchParam, mismatchBytes.data(), 0, 0);
}

