Cmis2x400GFr4WithMpiAlarmsTransceiver::Cmis2x400GFr4WithMpiAlarmsTransceiver(
    int module,
    TransceiverManager* mgr)
    : Cmis2x400GFr4Transceiver(module, mgr) {
  // Set PAM4 MPI alarm flags in page 2Ch, bytes 208-211
  // We'll set high alarm and high warning flags for all lanes

  // First, set the page to 0x2C
  TransceiverAccessParameter param(
      TransceiverAccessParameter::ADDR_QSFP, 127, 1);
  uint8_t page = 0x2C;
  writeTransceiver(param, &page, 0, 0);

  // Set high alarm and high warning flags for all lanes
  // Byte 208 (offset 80 in upper page): Lanes 0 and 1
  param.offset = 128 + 80;
  param.len = 1;
  uint8_t alarmValue = 0x55; // Set high alarm (bits 0,4) and high warning (bits
                             // 2,6) for both lanes
  writeTransceiver(param, &alarmValue, 0, 0);

  // Byte 209 (offset 81 in upper page): Lanes 2 and 3
  param.offset = 128 + 81;
  writeTransceiver(param, &alarmValue, 0, 0);

  // Byte 210 (offset 82 in upper page): Lanes 4 and 5
  param.offset = 128 + 82;
  writeTransceiver(param, &alarmValue, 0, 0);
  // Byte 211 (offset 83 in upper page): Lanes 6 and 7
  param.offset = 128 + 83;
  writeTransceiver(param, &alarmValue, 0, 0);
}

